from collections import deque

def components(a, color, adj8=False):
 h=len(a); w=len(a[0]); seen=set(); comps=[]
 shifts=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (adj8 or abs(dr)+abs(dc)==1)]
 for r in range(h):
  for c in range(w):
   if a[r][c]!=color or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for dr,dc in shifts:
     p=(x+dr,y+dc)
     if 0<=p[0]<h and 0<=p[1]<w and p not in seen and a[p[0]][p[1]]==color:
      seen.add(p); q.append(p)
   comps.append(comp)
 return comps
