 print(metric,'bad',len(bad), 'first',bad[:25])

# Compute non-7 seed-object distances for demo1; label objects by dominant color.
for adj8 in [False,True]:
 # components of cells in {5,9}
 def mask_components(a, allowed, adj8=False):
  h=len(a);w=len(a[0]);seen=set();cs=[];ds=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if dr or dc and (adj8 or abs(dr)+abs(dc)==1)]
  # fix logic
  ds=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (adj8 or abs(dr)+abs(dc)==1)]
  for r in range(h):
   for c in range(w):
    if a[r][c] not in allowed or (r,c) in seen: continue
    q=[(r,c)];seen.add((r,c));co=[]
    while q:
     x,y=q.pop();co.append((x,y))
     for dr,dc in ds:
      p=(x+dr,y+dc)
      if 0<=p[0]<h and 0<=p[1]<w and p not in seen and a[p[0]][p[1]] in allowed:
       seen.add(p);q.append(p)
    cs.append(co)
  return cs
