    dists=[]
    for comp in seeds_comps:
     d=min(abs(r-x)+abs(c-y) if metric=='manhattan' else math.hypot(r-x,c-y) for x,y in comp)
     dominant=Counter(demo_in[x][y] for x,y in comp).most_common(1)[0][0]
     dists.append((d,dominant))
    md=min(x[0] for x in dists)
